        void Patch(string name,RectInt r){var t=new Texture2D(r.width,r.height,TextureFormat.RGBA32,false);t.SetPixels(source.GetPixels(r.x,r.y,r.width,r.height));t.Apply();t.filterMode=FilterMode.Point;t.wrapMode=TextureWrapMode.Mirror;AssetDatabase.CreateAsset(t,"Assets/Resources/"+name+".asset");}
        Patch("NemoRiverWater",new RectInt(452,256,64,128));Patch("NemoRiverShallow",new RectInt(410,260,48,128));UnityEngine.Object.DestroyImmediate(source);AssetDatabase.SaveAssets();
