    static void Reset(Vector2 p){walk.Teleport(p);Physics2D.SyncTransforms();}
    static void Walk(string kind,string id,Vector2[] points)
    {
        var c=new Check{kind=kind,id=id,pass=true,start=points[0]};Reset(points[0]);foreach(var target in points.Skip(1)){int budget=Mathf.CeilToInt(Vector2.Distance(walk.BodyCenter,target)/.1f)+18;for(int k=0;k<budget&&Vector2.Distance(walk.BodyCenter,target)>.035f;k++){var d=target-walk.BodyCenter;walk.Actor.linearVelocity=d.normalized*Mathf.Min(5,d.magnitude/.02f);Physics2D.Simulate(.02f);c.steps++;}if(Vector2.Distance(walk.BodyCenter,target)>.06f){c.pass=false;c.error="Blocked before "+target;break;}}walk.Actor.linearVelocity=Vector2.zero;c.end=walk.BodyCenter;checks.Add(c);
    }
    public static void Probe()
