            walk=NemoBuilder.Create(0,true);capsule=walk.Actor.GetComponent<CapsuleCollider2D>();Physics2D.simulationMode=SimulationMode2D.Script;checks=new List<Check>();var map=walk.Map;
            foreach(var e in map.Plan.links){Walk("road-forward",e.a+"/"+e.b,e.points);Walk("road-reverse",e.b+"/"+e.a,e.points.Reverse().ToArray());}foreach(var approach in map.Approaches)Walk("facility-and-bank-approach",approach.parcel+" "+approach.prototype,approach.points);
            foreach(var bridge in map.AllBridges)Walk("bridge-present",bridge.name,new[]{bridge.West,bridge.East});Reset(map.Plan.parcels[0].hub);
            var result=new SeedResult{seed=0,riverBlocks=map.RiverNetwork.Design.blocks.Length,riverJoins=map.RiverNetwork.Design.joins.Length,roads=map.Plan.links.Length,roadOutlets=map.Plan.roadOutlets.Length,trees=map.Boundary.NativeTreeCount,criticalSkipped=map.Skipped.Count(p=>p.critical),success=checks.All(c=>c.pass)&&!map.Skipped.Any(p=>p.critical),checks=checks.ToArray(),errors=new string[0]};results.Add(result);NemoBuilder.Capture(walk.View,new Vector2(72,54),56,Path.Combine(NemoBuilder.Evidence,"river-seed-0-overview.png"),1728,1296);NemoBuilder.Capture(walk.View,map.RiverNetwork.Design.mainBridge,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"river-seed-0-main-bridge.png"));NemoBuilder.Capture(walk.View,map.RiverNetwork.Design.millBridge,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"river-seed-0-mill-bridge.png"));NemoBuilder.Persist(walk,ScenePath,"Assets/NemoBlocks/Generated/river-v3-seed-0");
        }catch(Exception e){errors.Add(e.ToString());Debug.LogException(e);}finally{Physics2D.simulationMode=SimulationMode2D.FixedUpdate;File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"river-probe.json"),JsonUtility.ToJson(new Report{success=errors.Count==0&&results.Count==1&&results.All(r=>r.success),seeds=results.ToArray(),errors=errors.ToArray(),scope=new[]{"Isolated Editor. Initial seed0 real Physics2D capsule routes and GPU images.","Incomplete full test; no owner Scene modification."}},true));Debug.Log("NEMO_RIVER_PROBE_COMPLETE");}
