    public static string RegionGeometry(NemoWalkRegion r)=>JsonUtility.ToJson(new RegionData{rooms=r.Rooms,ribbons=r.Ribbons,islands=r.ForestIslands,contours=r.Contours,mask=r.SavedGroundMask});
    [Serializable]class RegionData{public string mask;public NemoWalkRoom[] rooms,islands;public NemoWalkRibbon[] ribbons;public NemoWalkContour[] contours;}
    static bool Free(Vector2 p)=>!Physics2D.OverlapCapsuleAll(p,capsule.size,CapsuleDirection2D.Vertical,0).Any(c=>c!=capsule&&c.enabled&&!c.isTrigger);
    static bool WallProbe(NemoBoundaryWall wall,int side)
    {
        for(int i=1,spacing=Mathf.Max(1,Mathf.CeilToInt((wall.points.Length-1)/64f));i<wall.points.Length;i+=spacing){var point=(wall.points[i-1]+wall.points[i])/2;var tangent=(wall.points[i]-wall.points[i-1]).normalized;var normal=new Vector2(-tangent.y,tangent.x)*side;var start=point+normal*.95f;if(!walk.Map.Boundary.WalkRegion.Contains(start)||walk.Map.Boundary.WalkRegion.Contains(point-normal*.5f))continue;if(start.x<.4f||start.x>143.6f||start.y<.4f||start.y>107.6f||!Free(start))continue;bool obstructed=Enumerable.Range(0,12).Any(k=>Physics2D.OverlapCapsuleAll(point+normal*Mathf.Lerp(.95f,.30f,k/11f),capsule.size,CapsuleDirection2D.Vertical,0).Any(c=>c!=capsule&&c!=wall.collider&&c.enabled&&!c.isTrigger));if(obstructed)continue;Reset(start);bool touch=false;for(int k=0;k<35;k++){walk.Actor.linearVelocity=-normal*2;Physics2D.Simulate(.02f);touch|=capsule.IsTouching(wall.collider);}walk.Actor.linearVelocity=Vector2.zero;checks.Add(new Check{kind="boundary-wall-stop",id=wall.a+"/"+wall.b+" side "+side,touched=touch,insideGround=walk.Map.Boundary.WalkRegion.Contains(walk.BodyCenter),pass=touch&&walk.Map.Boundary.WalkRegion.Contains(walk.BodyCenter)&&Vector2.Distance(walk.BodyCenter,point-normal*.5f)>.20f,start=start,end=walk.BodyCenter,steps=35});return true;}return false;
    }
    static bool MajorRules(NemoPlan plan)
    {
        if(plan.links.Any(e=>plan.parcels[e.a].large&&plan.parcels[e.b].large))return false;foreach(var major in plan.parcels.Where(p=>p.large)){var reached=new HashSet<int>{major.id};var queue=new Queue<int>();queue.Enqueue(major.id);while(queue.Count>0){int node=queue.Dequeue();foreach(var e in plan.links.Where(e=>e.a==node||e.b==node)){int other=e.a==node?e.b:e.a;if(reached.Contains(other))continue;if(plan.parcels[other].large)return false;if(plan.parcels[other].land){reached.Add(other);queue.Enqueue(other);}}}}return true;
    }
