                    walk=NemoBuilder.Create(seed,true);capsule=walk.Actor.GetComponent<CapsuleCollider2D>();Physics2D.simulationMode=SimulationMode2D.Script;var map=walk.Map;var design=map.RiverNetwork.Design;
                    checks.Add(new Check{kind="river-outlets-continuous",id="position width direction and outside ends",pass=NemoRiverPlan.Validate(design).Length==0});
                    checks.Add(new Check{kind="preserved-area-and-quiet-distribution",id="same parcel purpose rectangle and quiet flags",pass=JsonUtility.ToJson(new ParcelDistribution{parcels=map.Plan.parcels.Select(p=>new NemoParcel{id=p.id,kind=p.kind,rect=p.rect,large=p.large,land=p.land,quiet=p.quiet}).ToArray()})==JsonUtility.ToJson(new ParcelDistribution{parcels=NemoLayout.Generate(seed).parcels.Select(p=>new NemoParcel{id=p.id,kind=p.kind,rect=p.rect,large=p.large,land=p.land,quiet=p.quiet}).ToArray()})});
                    checks.Add(new Check{kind="major-areas-separated-by-locations",pass=MajorRules(map.Plan)});checks.Add(new Check{kind="quiet-run-at-most-one",pass=!map.Plan.links.Any(e=>map.Plan.parcels[e.a].quiet&&map.Plan.parcels[e.b].quiet)});
