                    int probes=0,skips=0;foreach(var wall in map.Boundary.Walls){bool vertical=Mathf.Abs(wall.points[0].x-wall.points.Last().x)<.01f;int inside=vertical?(wall.points[0].x==0?-1:1):(wall.points[0].y==0?1:-1);foreach(int side in wall.outside?new[]{inside}:new[]{1,-1}){if(WallProbe(wall,side))probes++;else skips++;}}
                    foreach(var bridge in map.AllBridges){Walk("bridge-present",bridge.name,new[]{bridge.West,bridge.East});Walk("bridge-reverse",bridge.name,new[]{bridge.East,bridge.West});bridge.SetPresent(false);Reset(bridge.West);bool touched=false;for(int k=0;k<80;k++){walk.Actor.linearVelocity=Vector2.right*5;Physics2D.Simulate(.02f);touched|=bridge.GapBodies.Any(c=>capsule.IsTouching(c));}walk.Actor.linearVelocity=Vector2.zero;checks.Add(new Check{kind="bridge-removed-stop",id=bridge.name,pass=touched&&walk.BodyCenter.x<bridge.East.x-1});bridge.SetPresent(true);Walk("bridge-restored",bridge.name,new[]{bridge.West,bridge.East});}
                    int waterProbes=0;foreach(var block in design.blocks){if(waterProbes>=10)break;for(int i=1;i<block.points.Length;i++){var point=(block.points[i-1]+block.points[i])/2;if(point.x<4||point.x>140||point.y<4||point.y>104||map.AllBridges.Any(b=>Vector2.Distance(point,(b.West+b.East)/2)<4))continue;var tangent=(block.points[i]-block.points[i-1]).normalized;var normal=new Vector2(-tangent.y,tangent.x);var start=point+normal*(block.widths[i]/2+.9f);if(!Free(start))continue;bool obstructed=Enumerable.Range(0,20).Any(k=>Physics2D.OverlapCapsuleAll(Vector2.Lerp(start,point,(float)k/19),capsule.size,CapsuleDirection2D.Vertical,0).Any(c=>c!=capsule&&c.enabled&&!c.isTrigger&&!map.RiverNetwork.WaterBodies.Contains(c)));if(obstructed)continue;Reset(start);bool touch=false;for(int k=0;k<70;k++){walk.Actor.linearVelocity=-normal*2;Physics2D.Simulate(.02f);touch|=map.RiverNetwork.WaterBodies.Any(c=>capsule.IsTouching(c));}walk.Actor.linearVelocity=Vector2.zero;checks.Add(new Check{kind="river-water-stop",id=block.id+"/"+i,pass=touch&&Vector2.Dot(walk.BodyCenter-point,normal)>.5f,start=start,end=walk.BodyCenter});waterProbes++;break;}}
                    string regionGeometry=RegionGeometry(map.Boundary.WalkRegion),geometry=JsonUtility.ToJson(design),roadGeometry=JsonUtility.ToJson(map.Plan);Reset(map.Plan.parcels[0].hub);map.AllBridges[0].SetPresent(false);map.AllBridges[1].SetPresent(true);var position=walk.BodyCenter;walk.SaveNow();walk.Regenerate(seed+3);walk.LoadNow();map=walk.Map;checks.Add(new Check{kind="runtime-save-reload",id="river+road geometry, both bridge states, actor",pass=map.Seed==seed&&RegionGeometry(map.Boundary.WalkRegion)==regionGeometry&&JsonUtility.ToJson(map.RiverNetwork.Design)==geometry&&JsonUtility.ToJson(map.Plan)==roadGeometry&&!map.AllBridges[0].Present&&map.AllBridges[1].Present&&Vector2.Distance(walk.BodyCenter,position)<.001f});foreach(var b in map.AllBridges)b.SetPresent(true);
                    checks.Add(new Check{kind="native-scale-and-camera",pass=map.Mode=="Standard"&&walk.View.orthographicSize==NemoWalk.NormalCameraSize&&map.World.GetComponentsInChildren<SpriteRenderer>().All(s=>s.sprite!=null&&s.sprite.pixelsPerUnit==64&&s.transform.lossyScale==Vector3.one)});
                    string scene=seed==0?ScenePath:"Assets/NemoBlocks/Scenes/RiverSeeds/NemoRiverSeed"+seed+".unity";string assets="Assets/NemoBlocks/Generated/walk-v6-checked-seed-"+seed;if(AssetDatabase.IsValidFolder(assets))AssetDatabase.DeleteAsset(assets);Reset(map.Plan.parcels[0].hub);NemoBuilder.Persist(walk,scene,assets);EditorSceneManager.OpenScene(scene);walk=UnityEngine.Object.FindAnyObjectByType<NemoWalk>();capsule=walk.Actor.GetComponent<CapsuleCollider2D>();map=walk.Map;checks.Add(new Check{kind="saved-scene-reload",id=scene,pass=map.UseDesignedRivers&&RegionGeometry(map.Boundary.WalkRegion)==regionGeometry&&JsonUtility.ToJson(map.RiverNetwork.Design)==geometry&&JsonUtility.ToJson(map.Plan)==roadGeometry&&map.AllBridges.Length==2&&map.Boundary!=null&&map.Boundary.Walls.All(w=>w.collider!=null&&w.collider.enabled)&&map.RiverNetwork.WaterBodies.All(c=>c!=null&&c.enabled)});
                    Walk("reloaded-main-bridge","",new[]{map.Bridge.West,map.Bridge.East});foreach(var e in map.Plan.links)Walk("reloaded-road",e.a+"/"+e.b,e.points);
                    NemoBuilder.Capture(walk.View,new Vector2(72,54),56,Path.Combine(NemoBuilder.Evidence,"river-seed-"+seed+"-overview.png"),1728,1296);NemoBuilder.Capture(walk.View,map.Plan.parcels[0].hub,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"river-seed-"+seed+"-normal.png"));NemoBuilder.Capture(walk.View,map.RiverNetwork.Design.mainBridge,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"river-seed-"+seed+"-main-bridge.png"));NemoBuilder.Capture(walk.View,map.RiverNetwork.Design.millBridge,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"river-seed-"+seed+"-mill-bridge.png"));File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"river-seed-"+seed+"-plan.json"),JsonUtility.ToJson(map.Plan,true));File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"river-seed-"+seed+"-blocks.json"),JsonUtility.ToJson(map.RiverNetwork.Design,true));
                    result.riverBlocks=map.RiverNetwork.Design.blocks.Length;result.riverJoins=map.RiverNetwork.Design.joins.Length;result.roads=map.Plan.links.Length;result.roadOutlets=map.Plan.roadOutlets.Length;result.trees=map.Boundary.NativeTreeCount;result.criticalSkipped=map.Skipped.Count(s=>s.critical);result.quietRatio=(float)map.Plan.parcels.Count(p=>p.quiet)/map.Plan.parcels.Count(p=>!p.large&&!p.land);result.accessibleWallProbes=probes;result.wallProbeSkips=skips;result.waterProbes=waterProbes;checks.Add(new Check{kind="all-critical-locations-present",pass=result.criticalSkipped==0});
