    public static void RecheckBoundaryContacts(){var rows=new List<ContactRow>();try{foreach(int seed in new[]{0,17,42,99,20261011}){EditorSceneManager.OpenScene(seed==0?ScenePath:"Assets/NemoBlocks/Scenes/RiverSeeds/NemoRiverSeed"+seed+".unity");walk=UnityEngine.Object.FindAnyObjectByType<NemoWalk>();capsule=walk.Actor.GetComponent<CapsuleCollider2D>();checks=new List<Check>();Physics2D.simulationMode=SimulationMode2D.Script;int probes=0,skips=0;foreach(var wall in walk.Map.Boundary.Walls)foreach(int side in new[]{1,-1}){if(WallProbe(wall,side))probes++;else skips++;}rows.Add(new ContactRow{seed=seed,probes=probes,skipped=skips,checks=checks.ToArray(),success=probes>0&&checks.All(c=>c.pass)});Debug.Log("NEMO_NATURAL_CONTACT "+seed+" "+rows.Last().success);}}finally{Physics2D.simulationMode=SimulationMode2D.FixedUpdate;}File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"natural-forest-contact-verification.json"),JsonUtility.ToJson(new ContactReport{success=rows.Count==5&&rows.All(r=>r.success),seeds=rows.ToArray(),scope="Fresh actual Physics2D contacts on the five saved final Scenes. Up to 64 candidate points per contour/component. Contact required, actor centre must remain in design-derived walkable ground and must not reach the forbidden target. Corner sliding inside accessible ground is valid. Former straight-wall signed-distance failures retained separately."},true));EditorSceneManager.OpenScene(ScenePath);}
