e reopened in Unity 6000.4.3f1. All mesh/material/native sprite references, river/road outlet data, boundaries, actor/camera startup and GPU images checked. No regeneration or owner Editor modification."};File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"delivery-scene-inspection.json"),JsonUtility.ToJson(new Inspection{success=data.success,scene=data.scene,project=data.project,scope=data.scope,errors=data.errors,seed=data.seed,bridges=data.bridges,cameraSize=data.cameraSize,roads=data.roads,riverBlocks=data.riverBlocks,boundaryWalls=data.boundaryWalls,sceneDirty=data.sceneDirty},true));}
